"""
Near-miss laboratory: build, verify and cost Prouhet-Tarry-Escott near misses.

An integer weight vector e on the nodes 0..N with vanishing moments m_0, ..., m_{K-1}
splits into two multisets S (positive part) and T (negative part) with identical power
sums p_0, ..., p_{K-1}.  This script:

  * generates near misses as integer combinations of the translated binomial stencils,
    which is exhaustive by the structure theorem;
  * verifies the equal-power-sum property and reports the first divergence;
  * checks the congruence  sum_{x in S} (-1)^x  ==  sum_{x in T} (-1)^x   (mod 2^K);
  * compares the cost l1 = |S| + |T| against the proved floor and the conjectured 2K;
  * exhaustively confirms the proved floors at small windows.
"""

from __future__ import annotations

from itertools import product
from math import comb
from typing import Iterator, List, Optional, Sequence, Tuple

Vector = List[int]


def bin_weight(K: int, i: int, N: int) -> Vector:
    e = [0] * (N + 1)
    for d in range(K + 1):
        if i + d <= N:
            e[i + d] = (-1) ** (K - d) * comb(K, d)
    return e


def moment(e: Sequence[int], k: int) -> int:
    return sum(ej * (1 if (j == 0 and k == 0) else j**k) for j, ej in enumerate(e))


def l1(e: Sequence[int]) -> int:
    return sum(abs(x) for x in e)


def multisets(e: Sequence[int]) -> Tuple[List[int], List[int]]:
    S: List[int] = []
    T: List[int] = []
    for j, x in enumerate(e):
        if x > 0:
            S.extend([j] * x)
        elif x < 0:
            T.extend([j] * (-x))
    return S, T


def power_sum(S: Sequence[int], k: int) -> int:
    return sum(1 if (x == 0 and k == 0) else x**k for x in S)


def proved_floor(K: int) -> int:
    if K >= 3 and K % 2 == 1:
        return K + 3
    if K >= 2:
        return K + 2
    return K + 1


def generated_near_misses(N: int, K: int, crange: int = 1) -> Iterator[Vector]:
    """All integer combinations of the N+1-K stencils with coefficients bounded by crange."""
    M = max(0, N + 1 - K)
    for coeffs in product(range(-crange, crange + 1), repeat=M):
        if not any(coeffs):
            continue
        e = [0] * (N + 1)
        for i, c in enumerate(coeffs):
            if c:
                b = bin_weight(K, i, N)
                for j in range(N + 1):
                    e[j] += c * b[j]
        yield e


def describe(e: Sequence[int], K: int) -> str:
    S, T = multisets(e)
    for k in range(K):
        assert power_sum(S, k) == power_sum(T, k)
    gap = power_sum(S, K) - power_sum(T, K)
    alt = (sum((-1) ** x for x in S) - sum((-1) ** x for x in T)) % (2**K)
    assert alt == 0
    return (f"  {str(S):<28} vs {str(T):<28} cost {l1(e):>3}"
            f"   first gap at p_{K}: {gap:>6}   (mod 2^{K} congruence OK)")


def cheapest_generated(N: int, K: int, crange: int = 2) -> Tuple[int, Optional[Vector]]:
    best = (10**9, None)
    for e in generated_near_misses(N, K, crange):
        c = l1(e)
        if c < best[0]:
            best = (c, e)
    return best  # type: ignore[return-value]


def main() -> None:
    print("Near misses generated from the stencil basis (structure theorem: this is all")
    print("of them, up to the coefficient range used).\n")
    for N, K in [(4, 2), (6, 3), (8, 4)]:
        print(f"N = {N}, window K = {K}: the invisible lattice has rank {N + 1 - K}")
        shown = 0
        for e in generated_near_misses(N, K, crange=1):
            print(describe(e, K))
            shown += 1
            if shown == 5:
                break
        cost, best = cheapest_generated(N, K, crange=2)
        print(f"  cheapest in this range: cost {cost} at {best}")
        print(f"  proved floor {proved_floor(K)}, conjectured optimum {2 * K}\n")

    print("Exhaustive check of the proved floors on small ranges "
          "(entries bounded by 2):")
    for K, N in [(1, 3), (2, 4), (3, 5)]:
        best = (10**9, None)
        for cand in product(range(-2, 3), repeat=N + 1):
            if any(cand) and all(moment(cand, k) == 0 for k in range(K)):
                c = l1(cand)
                if c < best[0]:
                    best = (c, list(cand))
        cost, vec = best
        assert cost % 2 == 0 and cost >= proved_floor(K)
        print(f"  K = {K}: minimum cost {cost} (floor {proved_floor(K)}, 2K = {2 * K}) "
              f"attained by {vec}")


if __name__ == "__main__":
    main()

