"""Division-free descent: decompose an invisible weight vector over the stencil basis."""

from __future__ import annotations

from math import comb
from typing import List, Sequence

Vector = List[int]


def bin_weight(K: int, i: int, N: int) -> Vector:
    """The shifted alternating binomial stencil b^(K,i) on the nodes 0..N."""
    e = [0] * (N + 1)
    for d in range(K + 1):
        if i + d <= N:
            e[i + d] = (-1) ** (K - d) * comb(K, d)
    return e


def moment(e: Sequence[int], k: int) -> int:
    """m_k(e) = sum_j e_j j^k, with 0^0 = 1."""
    return sum(ej * (1 if (j == 0 and k == 0) else j**k) for j, ej in enumerate(e))


def is_invisible(e: Sequence[int], K: int) -> bool:
    """True iff the first K moments of e vanish."""
    return all(moment(e, k) == 0 for k in range(K))


def decompose_invisible(e: Sequence[int], N: int, K: int) -> List[int]:
    """
    Return the unique coefficients c_0, ..., c_{N-K} with e = sum_i c_i b^(K,i).

    The descent reads the coefficient off the top node, where exactly one stencil is
    supported and its entry is 1; hence no division is ever performed and integral
    input yields integral output.  Raises ValueError if e is not invisible.
    """
    work: Vector = list(e) + [0] * (N + 1 - len(e))
    coeffs: Vector = [0] * max(0, N + 1 - K)
    for i in range(len(coeffs) - 1, -1, -1):
        c = work[i + K]
        coeffs[i] = c
        if c:
            stencil = bin_weight(K, i, N)
            work = [a - c * b for a, b in zip(work, stencil)]
    if any(work):
        raise ValueError("the input vector is not invisible to the window K")
    return coeffs


def reconstruct(coeffs: Sequence[int], N: int, K: int) -> Vector:
    """Rebuild sum_i c_i b^(K,i) on the nodes 0..N."""
    out: Vector = [0] * (N + 1)
    for i, c in enumerate(coeffs):
        for j, b in enumerate(bin_weight(K, i, N)):
            out[j] += c * b
    return out


if __name__ == "__main__":
    e = [-1, 2, 0, -2, 1]  # window 3, the near miss {1,1,4} vs {0,3,3}
    assert is_invisible(e, 3)
    c = decompose_invisible(e, 4, 3)
    print("vector      :", e)
    print("coefficients:", c)
    print("rebuilt     :", reconstruct(c, 4, 3))

"""Convolution amplifier: build invisible vectors of large window and small cost."""

from __future__ import annotations

from math import comb
from typing import List, Sequence, Tuple

Vector = List[int]


def moment(e: Sequence[int], k: int) -> int:
    """m_k(e) = sum_j e_j j^k, with 0^0 = 1."""
    return sum(ej * (1 if (j == 0 and k == 0) else j**k) for j, ej in enumerate(e))


def window(e: Sequence[int], cap: int = 64) -> int:
    """The largest K <= cap with m_k(e) = 0 for all k < K."""
    K = 0
    while K < cap and moment(e, K) == 0:
        K += 1
    return K


def l1(e: Sequence[int]) -> int:
    """Total absolute weight."""
    return sum(abs(x) for x in e)


def convolve(w: Sequence[int], e: Sequence[int]) -> Vector:
    """Convolution of two weight vectors; generating polynomials multiply."""
    out: Vector = [0] * (len(w) + len(e) - 1)
    for a, wa in enumerate(w):
        if wa:
            for i, ei in enumerate(e):
                out[a + i] += wa * ei
    return out


def amplify(seed: Sequence[int], n: int) -> Vector:
    """The n-fold convolution power of the seed (n = 0 gives the unit [1])."""
    out: Vector = [1]
    for _ in range(n):
        out = convolve(out, seed)
    return out


def amplification_table(seed: Sequence[int], nmax: int) -> List[Tuple[int, int, int, int]]:
    """
    Rows (n, K, l1, 2^K) for the n-fold convolution powers of the seed.

    Windows add and l1 norms multiply, so with a seed of window K0 and cost L0 the
    n-th power has window at least n*K0 and cost at most L0^n; the comparison against
    2^K shows whether the seed beats the binomial stencil asymptotically, which it does
    exactly when L0 < 2^{K0}.  Complexity: O(n^2 * |seed| * len) integer operations.
    """
    rows: List[Tuple[int, int, int, int]] = []
    cur: Vector = [1]
    for n in range(1, nmax + 1):
        cur = convolve(cur, seed)
        K = window(cur)
        rows.append((n, K, l1(cur), 2**K))
    return rows


def leibniz_top_moment(w: Sequence[int], e: Sequence[int], Kw: int, Ke: int) -> Tuple[int, int]:
    """Check m_{Ke+Kw}(w*e) = C(Ke+Kw, Ke) m_{Ke}(e) m_{Kw}(w); return both sides."""
    c = convolve(w, e)
    return moment(c, Ke + Kw), comb(Ke + Kw, Ke) * moment(e, Ke) * moment(w, Kw)


if __name__ == "__main__":
    seed = [-1, 2, 0, -2, 1]  # window 3, cost 6 < 8 = 2^3
    print(" n   window K      l1        2^K      ratio")
    for n, K, cost, pw in amplification_table(seed, 6):
        print(f"{n:2d} {K:9d} {cost:9d} {pw:11d}   {cost / pw:.6f}")
    print("Leibniz check:", leibniz_top_moment([1, -2, 1], seed, 2, 3))

"""Exhaustive minimal-cost search for invisible vectors (near misses) on a small range."""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Optional, Sequence, Tuple

Vector = List[int]


def moment(e: Sequence[int], k: int) -> int:
    """m_k(e) = sum_j e_j j^k, with 0^0 = 1."""
    return sum(ej * (1 if (j == 0 and k == 0) else j**k) for j, ej in enumerate(e))


def l1(e: Sequence[int]) -> int:
    """Total absolute weight; equals the total size of the two multisets of a near miss."""
    return sum(abs(x) for x in e)


def minimal_cost(K: int, N: int, bound: int = 3) -> Tuple[Optional[int], Optional[Vector]]:
    """
    Cheapest nonzero vector on the nodes 0..N invisible to the window K, entries bounded
    by `bound` in absolute value.

    Meet-in-the-middle is possible, but the direct enumeration below is transparent:
    it iterates over (2*bound+1)^(N+1) candidates and evaluates K moments each, so the
    cost is O(K * N * (2b+1)^(N+1)).  Practical for N <= 8.
    """
    best_cost: Optional[int] = None
    best_vec: Optional[Vector] = None
    for cand in product(range(-bound, bound + 1), repeat=N + 1):
        if not any(cand):
            continue
        if all(moment(cand, k) == 0 for k in range(K)):
            c = l1(cand)
            if best_cost is None or c < best_cost:
                best_cost, best_vec = c, list(cand)
    return best_cost, best_vec


def near_miss(e: Sequence[int]) -> Tuple[List[int], List[int]]:
    """Split a weight vector into the two multisets of the corresponding near miss."""
    S: List[int] = []
    T: List[int] = []
    for j, x in enumerate(e):
        if x > 0:
            S.extend([j] * x)
        elif x < 0:
            T.extend([j] * (-x))
    return S, T


def proved_floor(K: int) -> int:
    """The proved lower bound on the cost: K+1, improved to K+2 (K>=2), K+3 (odd K>=3)."""
    if K >= 3 and K % 2 == 1:
        return K + 3
    if K >= 2:
        return K + 2
    return K + 1


def report(Kmax: int = 4, bound: int = 2) -> None:
    """Compare the observed minimal cost against the proved floor and the value 2K."""
    print(" K   N   min l1   proved floor   2K    witness")
    for K in range(1, Kmax + 1):
        N = 2 * K
        cost, vec = minimal_cost(K, N, bound)
        print(f"{K:2d} {N:3d} {cost!s:>8} {proved_floor(K):>14} {2*K:>5}    {vec}")


if __name__ == "__main__":
    report(Kmax=3, bound=2)
